abstract class Vehicle {
    protected String vin;
    protected double fuelLevel;

    public Vehicle(String vin, double fuelLevel) {
        this.vin = vin;
        this.fuelLevel = fuelLevel;
    }

    // Concrete method: Reusable across all vehicles
    public void refuel(double liters) {
        this.fuelLevel += liters;
        System.out.println("[" + vin + "] Refueled +" + liters + "L. Current: " + fuelLevel + "L");
    }

    // Abstract method: Every vehicle consumes fuel differently
    public abstract void drive(double distanceKm);
}

class ElectricCar extends Vehicle {
    public ElectricCar(String vin, double batteryKwh) {
        super(vin, batteryKwh);
    }

    @Override
    public void drive(double distanceKm) {
        double powerUsed = distanceKm * 0.2; // 0.2 kWh per km
        this.fuelLevel -= powerUsed;
        System.out.println("[EV " + vin + "] Drove " + distanceKm + "km. Battery remaining: " + String.format("%.1f", fuelLevel) + "kWh");
    }
}

public class VehicleDemo {
    public static void main(String[] args) {
        // Vehicle v = new Vehicle(...); // COMPILE ERROR
        Vehicle myTesla = new ElectricCar("5YJ3E1EB", 75.0);
        myTesla.drive(100.0);
        myTesla.refuel(15.0);
    }
}

