abstract class GraphicElement {
    protected int x, y;
    public GraphicElement(int x, int y) { this.x = x; this.y = y; }
    public abstract void render();
}

// Intermediate abstract class: Does NOT implement render(), adds new property
abstract class TwoDimensionalShape extends GraphicElement {
    protected String fillColor;
    public TwoDimensionalShape(int x, int y, String fillColor) {
        super(x, y);
        this.fillColor = fillColor;
    }
    // render() remains abstract! Legal because TwoDimensionalShape is abstract.
}

class Circle extends TwoDimensionalShape {
    private double radius;
    public Circle(int x, int y, String fillColor, double radius) {
        super(x, y, fillColor);
        this.radius = radius;
    }
    // Concrete leaf class MUST implement render()
    @Override
    public void render() {
        System.out.println("Drawing " + fillColor + " Circle at (" + x + "," + y + ") radius " + radius);
    }
}

public class GraphicDemo {
    public static void main(String[] args) {
        GraphicElement elem = new Circle(10, 20, "Red", 5.5);
        elem.render();
    }
}

