practiceProblems.solutionCode:
abstract class Worker {
    protected String name;
    protected double basePay;
    public Worker(String name, double basePay) {
        this.name = name;
        this.basePay = basePay;
    }
    public abstract double calculateSalary();
    public String getName() { return name; }
}

class FullTimeWorker extends Worker {
    public FullTimeWorker(String name, double basePay) {
        super(name, basePay);
    }
    @Override
    public double calculateSalary() {
        return basePay;
    }
}

class ContractWorker extends Worker {
    private int hoursWorked;
    public ContractWorker(String name, double hourlyRate, int hoursWorked) {
        super(name, hourlyRate);
        this.hoursWorked = hoursWorked;
    }
    @Override
    public double calculateSalary() {
        return basePay * hoursWorked;
    }
}

public class WorkerApp {
    public static void main(String[] args) {
        Worker[] team = new Worker[] {
            new FullTimeWorker("Alice", 4000.0),
            new ContractWorker("Bob", 50.0, 80)
        };
        for (Worker w : team) {
            System.out.println(w.getName() + ": $" + String.format("%.1f", w.calculateSalary()));
        }
    }
}

abstract class AbstractAccount {
    protected String accountNum;
    protected double balance;
    public AbstractAccount(String accountNum, double balance) {
        this.accountNum = accountNum;
        this.balance = balance;
    }
    public void deposit(double amt) {
        this.balance += amt;
    }
    public abstract boolean withdraw(double amt);
    public void printStatement() {
        System.out.println("[" + accountNum + "] Balance: $" + String.format("%.2f", balance));
    }
}

class CheckingAccount extends AbstractAccount {
    private double overdraftLimit;
    public CheckingAccount(String accountNum, double balance, double overdraftLimit) {
        super(accountNum, balance);
        this.overdraftLimit = overdraftLimit;
    }
    @Override
    public boolean withdraw(double amt) {
        if (balance + overdraftLimit >= amt) {
            balance -= amt;
            return true;
        }
        return false;
    }
}

public class BankApp {
    public static void main(String[] args) {
        AbstractAccount acc = new CheckingAccount("CHK-901", 100.0, 200.0);
        acc.deposit(50.0);
        acc.withdraw(200.0);
        acc.printStatement();
    }
}

abstract class DatabaseConnection {
    protected String url;
    public DatabaseConnection(String url) {
        this.url = url;
    }
    public abstract void connect();
    public abstract void executeQuery(String sql);
    public void runReport(String sql) {
        connect();
        executeQuery(sql);
    }
}

class PostgreSqlConnection extends DatabaseConnection {
    public PostgreSqlConnection(String url) {
        super(url);
    }
    @Override
    public void connect() {
        System.out.println("Connected to Postgres at " + url);
    }
    @Override
    public void executeQuery(String sql) {
        System.out.println("Executing Postgres query: " + sql);
    }
}

class MySqlConnection extends DatabaseConnection {
    public MySqlConnection(String url) {
        super(url);
    }
    @Override
    public void connect() {
        System.out.println("Connected to MySQL at " + url);
    }
    @Override
    public void executeQuery(String sql) {
        System.out.println("Executing MySQL query: " + sql);
    }
}

public class DbApp {
    public static void main(String[] args) {
        DatabaseConnection conn = new PostgreSqlConnection("jdbc:postgresql://localhost:5432/db");
        conn.runReport("SELECT * FROM metrics");
    }
}

