abstract class UiComponent {
    protected String id;
    public UiComponent(String id) {
        this.id = id;
    }
    public abstract void draw();
}

abstract class AbstractButton extends UiComponent {
    protected String label;
    public AbstractButton(String id, String label) {
        super(id);
        this.label = label;
    }
    public void click() {
        System.out.println("Button [" + label + "] clicked");
    }
}

class PrimaryButton extends AbstractButton {
    public PrimaryButton(String id, String label) {
        super(id, label);
    }
    @Override
    public void draw() {
        System.out.println("[PrimaryBtn ID: " + id + "] Rendering blue solid button: \"" + label + "\"");
    }
}

public class UiApp {
    public static void main(String[] args) {
        AbstractButton btn = new PrimaryButton("btn-login", "Log In");
        btn.draw();
        btn.click();
    }
}
